CREATE TABLE IF NOT EXISTS admins(id INTEGER PRIMARY KEY CHECK(id=1),username TEXT,pw TEXT);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT,first_name TEXT,chat_id INTEGER,blocked INTEGER DEFAULT 0,vip INTEGER DEFAULT 0,bot_limit INTEGER DEFAULT 1,vip_till INTEGER DEFAULT 0,state TEXT DEFAULT '',created INTEGER);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,kind TEXT,ref TEXT,csrf TEXT,exp INTEGER);
CREATE TABLE IF NOT EXISTS login_tokens(t TEXT PRIMARY KEY,owner INTEGER,exp INTEGER);
CREATE TABLE IF NOT EXISTS bots(id INTEGER PRIMARY KEY AUTOINCREMENT,owner INTEGER,token TEXT UNIQUE,username TEXT,name TEXT,secret TEXT,group_id INTEGER,group_name TEXT,status INTEGER DEFAULT 1,created INTEGER);
CREATE TABLE IF NOT EXISTS settings(scope TEXT,k TEXT,v TEXT,PRIMARY KEY(scope,k));
CREATE TABLE IF NOT EXISTS commands(id INTEGER PRIMARY KEY AUTOINCREMENT,bot INTEGER,name TEXT,resp TEXT);
CREATE TABLE IF NOT EXISTS auto_replies(id INTEGER PRIMARY KEY AUTOINCREMENT,bot INTEGER,trig TEXT,mode TEXT,resp TEXT);
CREATE TABLE IF NOT EXISTS warnings(bot INTEGER,uid INTEGER,n INTEGER DEFAULT 0,PRIMARY KEY(bot,uid));
CREATE TABLE IF NOT EXISTS stats(bot INTEGER,k TEXT,n INTEGER DEFAULT 0,PRIMARY KEY(bot,k));
CREATE TABLE IF NOT EXISTS logs(id INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT,msg TEXT,ts INTEGER);
CREATE INDEX IF NOT EXISTS i_bots_owner ON bots(owner);
CREATE INDEX IF NOT EXISTS i_cmd ON commands(bot,name);
CREATE INDEX IF NOT EXISTS i_logs ON logs(type,ts);
CREATE TABLE IF NOT EXISTS ai_providers(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT UNIQUE,name TEXT,act INTEGER DEFAULT 1);
INSERT OR IGNORE INTO ai_providers(kind,name) VALUES('openrouter','OpenRouter'),('gemini','Google Gemini'),('custom','Custom OpenAI-compatible');
CREATE TABLE IF NOT EXISTS ai_models(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT,model TEXT,prio INTEGER DEFAULT 10,free INTEGER DEFAULT 1,act INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS ai_usage(id INTEGER PRIMARY KEY AUTOINCREMENT,bot INTEGER,model TEXT,ok INTEGER,ts INTEGER);
CREATE TABLE IF NOT EXISTS cooldowns(bot INTEGER,uid INTEGER,till INTEGER,PRIMARY KEY(bot,uid));
CREATE TABLE IF NOT EXISTS msglog(bot INTEGER,uid INTEGER,ts INTEGER,h TEXT);
CREATE INDEX IF NOT EXISTS i_msglog ON msglog(bot,uid,ts);
CREATE TABLE IF NOT EXISTS scheduled_posts(id INTEGER PRIMARY KEY AUTOINCREMENT,bot INTEGER,body TEXT,run_at INTEGER,rep TEXT,mins INTEGER DEFAULT 60,act INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS buttons(id INTEGER PRIMARY KEY AUTOINCREMENT,bot INTEGER,scope TEXT,label TEXT,url TEXT);
CREATE TABLE IF NOT EXISTS join_buttons(id INTEGER PRIMARY KEY AUTOINCREMENT,label TEXT,url TEXT);
CREATE TABLE IF NOT EXISTS bot_admins(id INTEGER PRIMARY KEY AUTOINCREMENT,bot INTEGER,username TEXT,tg_id INTEGER,perms TEXT);
CREATE TABLE IF NOT EXISTS broadcasts(id INTEGER PRIMARY KEY AUTOINCREMENT,text TEXT,ts INTEGER);
CREATE TABLE IF NOT EXISTS bq(id INTEGER PRIMARY KEY AUTOINCREMENT,bid INTEGER,chat_id INTEGER,st INTEGER DEFAULT 0);
CREATE INDEX IF NOT EXISTS i_bq ON bq(bid,st);
